import { CRON_DEFINITIONS, discoverIncomeStreams, seedIncomeStreams } from '@taskman/core';

export const definition = CRON_DEFINITIONS.find(c => c.cronName === 'stream-discovery');

/**
 * Looks for ways this system could earn that it does not already know about.
 *
 * Every proposal is derived from rows the machine recorded itself and carries
 * the references that justify it. Nothing is generated by a model, and nothing
 * here promotes, enables or spends — a proposal lands as HYPOTHESIS and waits
 * for a judgement.
 */
export async function handler({ now = new Date() } = {}) {
  await seedIncomeStreams();
  return discoverIncomeStreams({ now });
}
